+    #[test]
+    #[ignore = "ordinary LSM append/update ownership ABBA at five scales; release single thread"]
+    fn lsm_owned_write_cost() {
+        use crate::lsm_tree::lsm_tree::{write_copy_reference, maintenance_probe};
+        let _run = crate::scale_probe::RunGuard::acquire("lsm_owned_write_cost");
+        crate::scale_probe::fingerprint();
+        let sizes: Vec<usize> = std::env::var("LSM_OWNED_ROWS")
+            .unwrap_or_else(|_| "600000,1000000,5000000,10000000,20000000".into())
+            .split(',').map(|s| s.trim().parse().unwrap()).collect();
+        assert!(!sizes.is_empty() && sizes[0] >= 1000 && sizes.windows(2).all(|w| w[0] < w[1]));
+        fn copy_seed(from: &Path, to: &Path) {
+            for entry in std::fs::read_dir(from).unwrap() {
+                let entry = entry.unwrap(); let kind = entry.file_type().unwrap();
+                let dest = to.join(entry.file_name());
+                if kind.is_dir() { std::fs::create_dir(&dest).unwrap(); copy_seed(&entry.path(), &dest); }
+                else { assert!(kind.is_file()); std::fs::copy(entry.path(), dest).unwrap(); }
+            }
+        }
+        let seed = ScaleScratch::new("lsm_owned_seed"); let mut built = 0;
+        for rows in sizes {
+            let db = crate::lsm_tree::MVCC::open(&seed.0);
+            for start in (built..rows).step_by(1000) {
+                let end = (start + 1000).min(rows);
+                let items: Vec<_> = (start..end).map(|i| (scale_key(i), scale_val(i))).collect();
+                let tx = db.begin_transaction(); tx.batch_set(&items).unwrap(); tx.try_commit().unwrap();
+                if end % 1_000_000 == 0 || end == rows { eprintln!("LSM_OWNED_BUILD rows={rows} completed={end}"); }
+            }
+            db.try_flush().unwrap(); db.try_checkpoint().unwrap(); drop(db); built = rows;
+            let writes = rows / 10; let mut outcomes = Vec::new();
+            for (round, reference) in [true, false, false, true].into_iter().enumerate() {
+                let dir = ScaleScratch::new("lsm_owned_arm"); copy_seed(&seed.0, &dir.0);
+                let db = crate::lsm_tree::MVCC::open(&dir.0);
+                let mode = reference.then(write_copy_reference::Scope::start);
+                let mut costs = Vec::new();
+                for update in [false, true] {
+                    let name = if update { "owned_update" } else { "owned_append" };
+                    eprintln!("LSM_OWNED_ARM rows={rows} round={round} reference={reference} phase={name} writes={writes}");
+                    let scope = maintenance_probe::Scope::start();
+                    let phase = crate::scale_probe::Phase::begin("lsm_tree", name);
+                    let before = crate::mem_probe::allocations();
+                    for start in (0..writes).step_by(1000) {
+                        let items: Vec<_> = (start..(start + 1000).min(writes)).map(|i| {
+                            if update { (scale_key(i), scale_val(i + 2 * rows)) }
+                            else { (scale_key(rows + i), scale_val(rows + i)) }
+                        }).collect();
+                        let tx = db.begin_transaction(); tx.batch_set(&items).unwrap(); tx.try_commit().unwrap();
+                    }
+                    costs.push(crate::mem_probe::allocations() - before);
+                    phase.finish("lsm_tree", name);
+                    eprintln!("LSM_OWNED_COST rows={rows} round={round} phase={name} allocations={} maintenance={:?}", costs.last().unwrap(), scope.stats());
+                }
+                drop(mode);
+                db.try_flush().unwrap(); db.try_checkpoint().unwrap(); drop(db);
+                let db = crate::lsm_tree::MVCC::open(&dir.0);
+                let mut seen = 0;
+                db.export_latest_visible_for_each(false, |record| {
+                    assert_eq!(record.key, scale_key(seen));
+                    assert_eq!(record.value, Some(scale_val(if seen < writes { seen + 2 * rows } else { seen })));
+                    seen += 1; true
+                });
+                assert_eq!(seen, rows + writes);
+                outcomes.push(costs);
+                eprintln!("LSM_OWNED_VERIFIED rows={rows} round={round} unique_keys={seen}");
+            }
+            for new in [1, 2] { for old in [0, 3] { for phase in 0..2 {
+                assert!(outcomes[new][phase] < outcomes[old][phase], "owned ordinary writes must reduce measured allocations");
+            } } }
+        }
+    }
