 #[cfg(test)]
 mod tests {
+    #[test]
+    fn ordinary_owned_write_retains_key_and_value_buffers() {
+        use crate::common::txn::WriteSide;
+        for ttl in [None, Some(u64::MAX)] {
+            for old in [true, false] {
+                let dir = tmp_dir("owned_buffers");
+                let mut opts = LSMTreeOptions::default();
+                opts.default_ttl_secs = ttl;
+                opts.enable_mem_wal = true;
+                let mut db = LSMTree::open_with_config(&dir, opts).unwrap();
+                let mut wal = crate::common::wal::Wal::open(dir.join("txn.wal")).unwrap();
+                let key = b"owned".to_vec(); let value = vec![7; 32];
+                let key_ptr = key.as_ptr(); let value_ptr = value.as_ptr();
+                let mode = old.then(write_copy_reference::Scope::start);
+                let mut side = crate::lsm_tree::lsm_tree_mvcc::TxnSide { kv: &mut db, wal: &mut wal };
+                assert!(side.put_versioned_owned(key, Some(value)));
+                drop(mode);
+                let (key, versions) = db.mem.get_key_value(b"owned".as_slice()).unwrap();
+                let EntryValue::Put(Some(value)) = versions.values().next().unwrap() else { panic!("expected value"); };
+                assert_eq!(key.as_ptr() == key_ptr, !old, "encoded key must reach memtable without cloning");
+                assert_eq!(value.as_ptr() == value_ptr, !old, "owned payload must reach memtable without cloning");
+                assert_eq!(db.ttl_meta.get(b"owned".as_slice()).copied(), ttl);
+            }
+        }
+    }
+
+    #[test]
+    fn ordinary_owned_write_preserves_stats_ttl_wal_and_blobs() {
+        for ttl in [None, Some(u64::MAX)] {
+            for mem_wal in [false, true] {
+                for blob_threshold in [8, usize::MAX] {
+                    let mut outcomes = Vec::new();
+                    for old in [true, false] {
+                        let dir = tmp_dir("owned_semantics");
+                        let mut opts = LSMTreeOptions::default();
+                        opts.default_ttl_secs = ttl;
+                        opts.enable_mem_wal = mem_wal;
+                        opts.blob_threshold = blob_threshold;
+                        let mut db = LSMTree::open_with_config(&dir, opts.clone()).unwrap();
+                        let mode = old.then(write_copy_reference::Scope::start);
+                        for (key, value) in [(b"a", Some(vec![1; 32])), (b"a", Some(vec![2; 48])),
+                            (b"b", None), (b"c", Some(vec![])), (b"a", None), (b"a", Some(vec![5; 16]))] {
+                            db.insert(key.to_vec(), value);
+                        }
+                        drop(mode);
+                        assert_eq!((db.cached_live, db.cached_tomb), (2, 2));
+                        assert!(!db.ttl_meta.contains_key(b"b".as_slice()));
+                        outcomes.push((db.mem.clone(), db.mem_entries, db.mem_bytes, db.cached_live,
+                            db.cached_tomb, db.ttl_meta.clone(), db.write_seq.load(Ordering::SeqCst)));
+                        assert_eq!(db.get(b"a"), Some(vec![5; 16]));
+                        if ttl.is_some() {
+                            db.ttl_meta.insert(b"a".to_vec(), 0);
+                            assert_eq!(db.get(b"a"), None);
+                            db.ttl_meta.insert(b"a".to_vec(), u64::MAX);
+                        }
+                        db.flush().unwrap(); drop(db);
+                        let db = LSMTree::open_with_config(&dir, opts).unwrap();
+                        assert_eq!(db.get(b"a"), Some(vec![5; 16]));
+                        assert_eq!(db.get(b"b"), None);
+                        assert_eq!(db.get(b"c"), Some(vec![]));
+                    }
+                    assert_eq!(outcomes[0], outcomes[1]);
+                }
+            }
+        }
+    }
